#include <iostream>
#include <string>
#include <stdexcept>
class Parser {
    const std::string& s;
    std::size_t pos;
    void space() { while (pos < s.size() && s[pos] == ' ') ++pos; }
    long long bounded(long long x) {
        if (x < -1000000 || x > 1000000) throw std::runtime_error("range");
        return x;
    }
    long long number() {
        space();
        const std::size_t start = pos;
        long long x = 0;
        while (pos < s.size() && s[pos] >= '0' && s[pos] <= '9') {
            // 세 번째 자리는 값을 곱하기 전에 거절합니다.
            if (pos - start == 2) throw std::runtime_error("digits");
            x = x * 10 + (s[pos++] - '0');
        }
        if (pos == start) throw std::runtime_error("number");
        return x;
    }
    long long term() {
        long long x = number();
        while (true) {
            space();
            if (pos == s.size() || s[pos] != '*') return x;
            ++pos;
            x = bounded(x * number()); // 이전 항은 범위 안, 새 숫자는 최대 99입니다.
        }
    }
public:
    explicit Parser(const std::string& text) : s(text), pos(0) {}
    long long parse() {
        long long x = term();
        while (true) {
            space();
            if (pos == s.size()) return x;
            const char op = s[pos++];
            if (op != '+' && op != '-') throw std::runtime_error("operator");
            const long long y = term();
            x = bounded(op == '+' ? x + y : x - y);
        }
    }
};
int main() {
    std::string s, extra;
    if (!std::getline(std::cin, s) || s.size() > 1000 || std::getline(std::cin, extra)) {
        std::cout << "ERROR\n"; return 0;
    }
    try { Parser p(s); std::cout << p.parse() << '\n'; }
    catch (const std::runtime_error&) { std::cout << "ERROR\n"; }
}
